refentry.refsect1:
&reftitle.changelog;





    &Version;
    &Description;





    8.0.0

     定数が定義されていない場合は、
     constant は
     Error をスローするようになりました。
     これより前のバージョンでは、
     E_WARNING
     レベルの警告が発生し、&null; を返していました。

  &reftitle.examples;



    定数に対して constant を使う例


<?php

define("MAXSIZE", 100);

echo MAXSIZE;
echo constant("MAXSIZE"); // same thing as the previous line


interface bar {
    const test = 'foobar!';
}

class foo {
    const test = 'foobar!';
}

$const = 'test';

var_dump(constant('bar::'. $const)); // string(7) "foobar!"
var_dump(constant('foo::'. $const)); // string(7) "foobar!"

?>




    列挙型の case に constant を使う例(PHP 8.1.0 以降)


<?php

enum Suit
{
    case Hearts;
    case Diamonds;
    case Clubs;
    case Spades;
}

$case = 'Hearts';

var_dump(constant('Suit::'. $case)); // enum(Suit::Hearts)

?>
